insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, created_at, package_id, package_version, license, attribution, outline) values ('l-lib-aesop-for-children', 'Aesop, illustrated by Milo Winter', 'open', false, 'The Aesop for Children', array['reading', 'writing']::text[], 0, 3, array['charlotte_mason', 'classical', 'traditional']::text[], 'online', 0, 'The classic 1919 Aesop collection with Milo Winter''s beloved pictures: 147 short fables, each ending in a moral. Read three fables aloud, let your child tell them back, and copy one moral as handwriting practice. The full illustrated text is free online.', array['49 lessons in 7 units', 'All 147 fables, three per lesson', 'Narration and copywork every lesson', 'One question per fable with a kid-friendly answer', 'Link to the free illustrated text for every fable']::text[], 49, 3, 20, 'high', true, '{}'::text[], '🦊', '#E3A33B', false, '2026-11-11T12:00:00.000Z', 'pk-lib-aesop-for-children', 1, '{"kind":"public_domain"}'::jsonb, '“The Aesop for Children, with Pictures by Milo Winter” by Aesop (illustrated by Milo Winter) (1919), in the public domain. Free full text: https://www.gutenberg.org/ebooks/19994. Lesson plan by Freerange.', '[{"title":"Unit 1: Fables 1–21","lessons":["Lesson 1: The Wolf and the Kid, The Tortoise and the Ducks, The Young Crab and His Mother","Lesson 2: The Frogs and the Ox, The Dog, the Cock, and the Fox, Belling the Cat","Lesson 3: The Eagle and the Jackdaw, The Boy and the Filberts, Hercules and the Wagoner","Lesson 4: The Kid and the Wolf, The Town Mouse and the Country Mouse, The Fox and the Grapes","Lesson 5: The Bundle of Sticks, The Wolf and the Crane, The Ass and His Driver","Lesson 6: The Oxen and the Wheels, The Lion and the Mouse, The Shepherd Boy and the Wolf","Lesson 7: The Gnat and the Bull, The Plane Tree, The Farmer and the Stork"]},{"title":"Unit 2: Fables 22–42","lessons":["Lesson 8: The Sheep and the Pig, The Travelers and the Purse, The Lion and the Ass","Lesson 9: The Frogs Who Wished for a King, The Owl and the Grasshopper, The Wolf and His Shadow","Lesson 10: The Oak and the Reeds, The Rat and the Elephant, The Boys and the Frogs","Lesson 11: The Crow and the Pitcher, The Ants and the Grasshopper, The Ass Carrying the Image","Lesson 12: A Raven and a Swan, The Two Goats, The Ass and the Load of Salt","Lesson 13: The Lion and the Gnat, The Leap at Rhodes, The Cock and the Jewel","Lesson 14: The Monkey and the Camel, The Wild Boar and the Fox, The Ass, the Fox, and the Lion"]},{"title":"Unit 3: Fables 43–63","lessons":["Lesson 15: The Birds, the Beasts, and the Bat, The Lion, the Bear, and the Fox, The Wolf and the Lamb","Lesson 16: The Wolf and the Sheep, The Hares and the Frogs, The Fox and the Stork","Lesson 17: The Travelers and the Sea, The Wolf and the Lion, The Stag and His Reflection","Lesson 18: The Peacock, The Mice and the Weasels, The Wolf and the Lean Dog","Lesson 19: The Fox and the Lion, The Lion and the Ass, The Dog and His Master''s Dinner","Lesson 20: The Vain Jackdaw and His Borrowed Feathers, The Monkey and the Dolphin, The Wolf and the Ass","Lesson 21: The Monkey and the Cat, The Dogs and the Fox, The Dogs and the Hides"]},{"title":"Unit 4: Fables 64–84","lessons":["Lesson 22: The Rabbit, the Weasel, and the Cat, The Bear and the Bees, The Fox and the Leopard","Lesson 23: The Heron, The Cock and the Fox, The Dog in the Manger","Lesson 24: The Wolf and the Goat, The Ass and the Grasshoppers, The Mule","Lesson 25: The Fox and the Goat, The Cat, the Cock, and the Young Mouse, The Wolf and the Shepherd","Lesson 26: The Peacock and the Crane, The Farmer and the Cranes, The Farmer and His Sons","Lesson 27: The Two Pots, The Goose and the Golden Egg, The Fighting Bulls and the Frog","Lesson 28: The Mouse and the Weasel, The Farmer and the Snake, The Sick Stag"]},{"title":"Unit 5: Fables 85–105","lessons":["Lesson 29: The Goatherd and the Wild Goats, The Spendthrift and the Swallow, The Cat and the Birds","Lesson 30: The Dog and the Oyster, The Astrologer, Three Bullocks and a Lion","Lesson 31: Mercury and the Woodman, The Frog and the Mouse, The Fox and the Crab","Lesson 32: The Serpent and the Eagle, The Wolf in Sheep''s Clothing, The Bull and the Goat","Lesson 33: The Eagle and the Beetle, The Old Lion and the Fox, The Man and the Lion","Lesson 34: The Ass and the Lap Dog, The Milkmaid and Her Pail, The Wolf and the Shepherd","Lesson 35: The Goatherd and the Goat, The Miser, The Wolf and the House Dog"]},{"title":"Unit 6: Fables 106–126","lessons":["Lesson 36: The Fox and the Hedgehog, The Bat and the Weasels, The Quack Toad","Lesson 37: The Fox Without a Tail, The Mischievous Dog, The Rose and the Butterfly","Lesson 38: The Cat and the Fox, The Boy and the Nettle, The Old Lion","Lesson 39: The Fox and the Pheasants, Two Travelers and a Bear, The Porcupine and the Snakes","Lesson 40: The Fox and the Monkey, The Mother and the Wolf, The Flies and the Honey","Lesson 41: The Eagle and the Kite, The Stag, the Sheep, and the Wolf, The Animals and the Plague","Lesson 42: The Shepherd and the Lion, The Dog and His Reflection, The Hare and the Tortoise"]},{"title":"Unit 7: Fables 127–147","lessons":["Lesson 43: The Bees and Wasps, and the Hornet, The Lark and Her Young Ones, The Cat and the Old Rat","Lesson 44: The Fox and the Crow, The Ass and Its Shadow, The Miller, His Son, and the Ass","Lesson 45: The Ant and the Dove, The Man and the Satyr, The Wolf, the Kid, and the Goat","Lesson 46: The Swallow and the Crow, Jupiter and the Monkey, The Lion, the Ass, and the Fox","Lesson 47: The Lion''s Share, The Mole and His Mother, The North Wind and the Sun","Lesson 48: The Hare and His Ears, The Wolves and the Sheep, The Cock and the Fox","Lesson 49: The Ass in the Lion''s Skin, The Fisherman and the Little Fish, The Fighting Cocks and the Eagle"]}]'::jsonb)
